cloud_init.template:
#cloud-config
password: {{ admin_password | yaml }}
chpasswd: { expire: False }
ssh_pwauth: True
{% if net.mode == 'static' %}

bootcmd:
  - ip addr add {{ net.ip }}/{{ net.prefix }} dev ens3
  - ip link set ens3 up
{% if net.gateway %}
  - ip route add default via {{ net.gateway }}
{% endif %}
{% endif %}

write_files:
{% if net.mode == 'static' %}
  - path: /etc/netplan/99-static.yaml
    permissions: '0600'
    content: |
      network:
        version: 2
        ethernets:
          ens3:
            addresses:
              - {{ net.ip }}/{{ net.prefix }}
{% if net.gateway %}
            routes:
              - to: default
                via: {{ net.gateway }}
{% endif %}
            nameservers:
              addresses: {{ net.dns | yaml }}
              search: {{ net.search | yaml }}
{% endif %}
  - path: /etc/hosts
    append: true
    content: |
      # VMware endpoints
{% if vcenter_ip and vcenter_fqdn %}
      {{ vcenter_ip }} {{ vcenter_fqdn }}
{% endif %}
      # OpenStack / PCD endpoints
{% if pcd_ip and pcd_fqdn %}
      {{ pcd_ip }} {{ pcd_fqdn }}
{% endif %}
{% if net.mode == 'static' %}

runcmd:
  - netplan apply
{% endif %}
